// Lit la reponse finale de agent-analyste (un objet JSON, cf. competence-rediger-comptes-rendus).
const sortie = $input.first().json;
let reponse = null;
try {
  // la derniere ligne JSON de la sortie : d'eventuels avertissements la precedent
  const ligne = String(sortie.stdout || '').split(String.fromCharCode(10)).reverse().find(l => l.trim().startsWith('{'));
  const enveloppe = JSON.parse(ligne);
  const texte = String(enveloppe.result ?? '');
  if (!enveloppe.is_error) reponse = JSON.parse(texte.slice(texte.indexOf('{'), texte.lastIndexOf('}') + 1));
} catch (e) { /* reponse illisible : traitee ci-dessous */ }
if (!reponse || !reponse.statut) {
  reponse = {
    statut: 'bloque',
    resume: "L'agent n'a pas renvoyé de réponse lisible.",
    prochaine_action: "Ouvrir cette exécution dans n8n et lire la sortie de la boîte « Agent analyste ».",
    sortie_brute: String(sortie.stdout || sortie.stderr || sortie.error || '(aucune sortie)').slice(0, 1500),
  };
}
return [{ json: { agent: 'agent-analyste', ...reponse } }];

