// Rassemble ce qu'un humain doit savoir quand un agent (ou Squash) est bloque.
const r = $input.first().json;
const agent = r.agent || 'Squash (changement de statut du cas)';
const resume = r.resume || r.error || r.stderr || 'cause inconnue';
const action = r.prochaine_action || "Ouvrir l'exécution dans n8n pour voir le détail.";
const message =
  '*🛑 Cycle QA automatisé interrompu*\n\n' +
  '*Étape bloquée* : ' + agent + '\n' +
  '*Pourquoi* : ' + resume + '\n' +
  '*À faire* : ' + action + '\n\n' +
  "Une fois le problème réglé, demander à Claude de retester cette story (par exemple « teste " + $('Contexte de la story').first().json.cleStory + " »).";
return [{ json: { agent, resume, action, message } }];

// Un element par bug Jira declare ou retrouve par le gestionnaire d'anomalies.
const r = $('Réponse gestionnaire').last().json;
return (r.anomalies || [])
  .filter(a => /^[A-Z][A-Z0-9]+-\d+$/.test(String(a.cle || '')))
  .map(a => ({ json: { cle: a.cle, titre: String(a.titre || '').slice(0, 150), cas: String(a.cas || ''), nouveau: a.nouveau === true } }));
